import RNA, random, sys, itertools

target = "((...((....((.....((.........((..............................))...............)).........)).......))....))...."
n = len(target)
pairs = [(0,105),(1,104),(5,99),(6,98),(11,90),(12,89),(18,79),(19,78),(29,62),(30,61)]
# 5 stems
stems = [(pairs[0],pairs[1]), (pairs[2],pairs[3]), (pairs[4],pairs[5]), (pairs[6],pairs[7]), (pairs[8],pairs[9])]

def fold(s):
    fc = RNA.fold_compound(s)
    ss, _ = fc.mfe()
    return ss

def bd(s):
    return RNA.bp_distance(fold(s), target)

# Build seq from stem orientations (5 stems, each GC or CG) + loop dict
def build(oris, loopd):
    seq = ['A']*n
    for k, (p1, p2) in enumerate(stems):
        o = oris[k]
        seq[p1[0]]=o[0]; seq[p1[1]]=o[1]
        seq[p2[0]]=o[0]; seq[p2[1]]=o[1]
    for p,c in loopd.items():
        seq[p]=c
    return ''.join(seq)

best_bd = 999; best_seq = None; best_oris=None; best_loop={}
random.seed(7)

# Phase 1: all 32 orientations
for combo in itertools.product(['GC','CG'], repeat=5):
    s = build(combo, {})
    d = bd(s)
    if d < best_bd:
        best_bd=d; best_seq=s; best_oris=combo; best_loop={}
print("P1 best:", best_bd, best_oris, flush=True)

# Phase 2: local search on loop positions (keep stems fixed at best_oris)
unpaired = [i for i in range(n) if target[i]=='.']
for restart in range(20):
    loopd = dict(best_loop)
    cur_bd = best_bd
    for it in range(2000):
        la = dict(loopd)
        for _ in range(random.randint(1,4)):
            p = random.choice(unpaired)
            la[p] = random.choice('ACGU')
        s = build(best_oris, la)
        d = bd(s)
        if d <= cur_bd:
            if d < cur_bd:
                if d < best_bd:
                    best_bd=d; best_seq=s; best_loop=dict(la)
                    print(f"r{restart} it{it}: bd={d} {s}", flush=True)
            loopd = la
            cur_bd = d
        if best_bd == 0:
            break
    if best_bd == 0:
        break
    # random restart: randomize loopd occasionally
    if restart % 5 == 4:
        loopd = {p: random.choice('ACGU') for p in unpaired[:8]}

print("FINAL bd:", best_bd, flush=True)
print("FINAL_SEQUENCE:", best_seq, flush=True)

